// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(amount <= address(c).balance);
        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        bool ok = true;
        try c.sendMoney(address(0xdead), 0) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}
